package vn.covie.reputation.application; import java.util.List; import org.springframework.stereotype.Component; import vn.covie.outbox.application.*; import vn.covie.realtime.SseSignal;
@Component public class OrderReputationOutboxHandler implements OutboxEventHandler {private final ReputationProjectionService projection;public OrderReputationOutboxHandler(ReputationProjectionService projection){this.projection=projection;}public boolean supports(String eventType){return eventType.startsWith("ORDER_");}public List<SseSignal> handle(OutboxEventContext event){projection.projectOrder(event.aggregateId(),event.eventId());return List.of();}}
